import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as commentService from "@/server/services/comment-service";
import * as attachmentService from "@/server/services/attachment-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let issue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("frozenproj");

  issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Stays live" }),
  );

  await projectService.archiveProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    archiveIssues: false,
  });
});

afterAll(() => {
  cleanup();
});

describe("archived project freeze", () => {
  it("issue is still live but reads still work", async () => {
    const fresh = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(fresh.issue.archivedAt).toBeNull();
  });

  it("blocks updateIssue", async () => {
    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "nope",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("blocks changeIssueStatus", async () => {
    await expect(
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "done",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("blocks assignIssue", async () => {
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("blocks archiveIssue", async () => {
    await expect(
      issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("blocks createComment", async () => {
    await expect(
      commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "hi",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("blocks addAttachment", async () => {
    await expect(
      attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        fileName: "a.txt",
        sizeBytes: 10,
        contentType: "text/plain",
        url: "https://example.com/a.txt",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("lets restore lift the freeze", async () => {
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id);

    const after = await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "works now",
    });
    expect(after.title).toBe("works now");
  });
});

