import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { subscribe } from "@/lib/event-bus";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterAll(() => {
  cleanup();
});

describe("overdue sweep respects archived project", () => {
  it("does not announce an issue whose project is archived", async () => {
    const tenant: Tenant = await createTenant("overdue-frozen");
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Late", dueAt: PAST }),
      tenant.userIds.owner,
      number,
    );

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      seen.push(payload.issueId);
    });

    try {
      await runOverdueIssueJob(NOW);
      expect(seen).not.toContain(issue.id);

      await projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
      await runOverdueIssueJob(new Date(NOW.getTime() + 1000));
      expect(seen).toContain(issue.id);
    } finally {
      off();
    }
  });
});

